INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('dreams-026', 'dreams', 'Picture a really good year for us, a year from now. What did we do, what did we change, and what stayed the same?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-027', 'dreams', 'Where in the world could you picture us making a life, and what pulls you toward each place?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-028', 'dreams', 'What’s an adventure you’d love for us to have in the next five years, and what would make it feel like ours?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-029', 'dreams', 'Five years from now, what do you hope our life has more of, and what do you hope it has less of?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-030', 'dreams', 'Who do you hope is around us in the years ahead—friends, family, a community—and how could we make room for them now?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-031', 'dreams', 'When you think about our future, what are you most excited about, and what do you quietly worry about?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-032', 'dreams', 'How do you want us to make the big decisions ahead of us—where to live, work, family—so that we choose on purpose instead of drifting?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-033', 'dreams', 'If one of us got a big opportunity that upended our plans, how would you want us to weigh it together?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-034', 'dreams', 'What does enough look like to you—enough money, success, adventure—and how would we know we’d reached it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-035', 'dreams', 'Ten years from now, what would you want our work to make possible for us, and what would you never want it to cost us?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-036', 'dreams', 'What hope for our future have you never said out loud, and what has kept you from saying it?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-037', 'dreams', 'How do you picture us growing old together—our days, our health, the ways we look after each other?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-038', 'dreams', 'If our hopes for the future pulled in different directions, how would you want us to find a path that honors both of us?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000)
